<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Personal Expense Tracker</title>
  <style>
    * { box-sizing: border-box; }
    body {
      margin: 0;
      background: #f3f5f8;
      color: #1d2939;
      font: 16px/1.4 system-ui, sans-serif;
    }
    main {
      max-width: 780px;
      margin: 32px auto;
      padding: 24px;
      background: white;
      border-radius: 12px;
      box-shadow: 0 4px 18px #00000012;
    }
    h1, h2 { margin: 0 0 16px; }
    h2 { font-size: 1.15rem; margin-top: 28px; }
    form, .filters {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(145px, 1fr));
      gap: 12px;
      align-items: end;
    }
    label { display: grid; gap: 5px; font-weight: 600; font-size: .9rem; }
    input, select, button {
      width: 100%;
      padding: 9px 10px;
      border: 1px solid #c8d0da;
      border-radius: 6px;
      font: inherit;
    }
    button {
      border: 0;
      background: #166534;
      color: white;
      cursor: pointer;
      font-weight: 700;
    }
    button:hover { background: #14532d; }
    #form-error { min-height: 1.4em; margin: 10px 0 0; color: #b42318; }
    .summary {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
      gap: 10px;
      margin-top: 12px;
    }
    .summary > div {
      padding: 12px;
      background: #f8fafc;
      border-radius: 7px;
    }
    #total { font-size: 1.45rem; font-weight: 800; }
    #expenses { display: grid; gap: 8px; margin-top: 12px; }
    .expense {
      display: grid;
      grid-template-columns: 110px 1fr 120px auto;
      gap: 12px;
      align-items: center;
      padding: 12px;
      background: #f8fafc;
      border-radius: 7px;
    }
    .expense-note { color: #667085; font-size: .9rem; }
    .exp-del {
      width: auto;
      padding: 7px 10px;
      background: #b42318;
    }
    .exp-del:hover { background: #8d1b12; }
    .empty { color: #667085; padding: 12px 0; }
    @media (max-width: 540px) {
      .expense { grid-template-columns: 1fr auto; }
      .expense-date, .expense-note { grid-column: 1; }
      .exp-del { grid-column: 2; grid-row: 1 / span 2; }
    }
  </style>
</head>
<body>
  <main>
    <h1>Expense Tracker</h1>

    <form id="expense-form" novalidate>
      <label>Amount
        <input id="amount" type="number" min="0.01" step="0.01" inputmode="decimal">
      </label>
      <label>Category
        <select id="category">
          <option value="groceries">Groceries</option>
          <option value="transport">Transport</option>
          <option value="bills">Bills</option>
          <option value="fun">Fun</option>
        </select>
      </label>
      <label>Date
        <input id="date" type="date">
      </label>
      <label>Note
        <input id="note" type="text" maxlength="200" placeholder="Optional">
      </label>
      <button id="add-expense" type="submit">Add expense</button>
    </form>
    <div id="form-error" role="alert" aria-live="polite"></div>

    <h2>Filters</h2>
    <div class="filters">
      <label>Category
        <select id="filter-category">
          <option value="all">All categories</option>
          <option value="groceries">Groceries</option>
          <option value="transport">Transport</option>
          <option value="bills">Bills</option>
          <option value="fun">Fun</option>
        </select>
      </label>
      <label>From <input id="filter-from" type="date"></label>
      <label>To <input id="filter-to" type="date"></label>
    </div>

    <h2>Visible total: <span id="total">0.00</span></h2>
    <div class="summary">
      <div class="cat-total" data-cat="groceries">Groceries: 0.00</div>
      <div class="cat-total" data-cat="transport">Transport: 0.00</div>
      <div class="cat-total" data-cat="bills">Bills: 0.00</div>
      <div class="cat-total" data-cat="fun">Fun: 0.00</div>
    </div>

    <h2>Expenses</h2>
    <div id="expenses"></div>
  </main>

  <script>
    (function () {
      const categories = ["groceries", "transport", "bills", "fun"];
      const storageKey = "personal-expense-tracker-expenses";
      const form = document.getElementById("expense-form");
      const amountInput = document.getElementById("amount");
      const categoryInput = document.getElementById("category");
      const dateInput = document.getElementById("date");
      const noteInput = document.getElementById("note");
      const error = document.getElementById("form-error");
      const list = document.getElementById("expenses");
      const filterCategory = document.getElementById("filter-category");
      const filterFrom = document.getElementById("filter-from");
      const filterTo = document.getElementById("filter-to");
      const total = document.getElementById("total");

      let expenses = loadExpenses();

      function loadExpenses() {
        try {
          const saved = JSON.parse(localStorage.getItem(storageKey));
          return Array.isArray(saved) ? saved.filter(function (item) {
            return item && categories.includes(item.category) &&
              typeof item.date === "string" && Number(item.amount) > 0;
          }) : [];
        } catch (_) {
          return [];
        }
      }

      function saveExpenses() {
        localStorage.setItem(storageKey, JSON.stringify(expenses));
      }

      function visibleExpenses() {
        return expenses.filter(function (expense) {
          const categoryMatch = filterCategory.value === "all" ||
            expense.category === filterCategory.value;
          const fromMatch = !filterFrom.value || expense.date >= filterFrom.value;
          const toMatch = !filterTo.value || expense.date <= filterTo.value;
          return categoryMatch && fromMatch && toMatch;
        });
      }

      function render() {
        const visible = visibleExpenses();
        list.textContent = "";

        if (visible.length === 0) {
          const empty = document.createElement("div");
          empty.className = "empty";
          empty.textContent = "No expenses match these filters.";
          list.appendChild(empty);
        }

        visible.forEach(function (expense) {
          const row = document.createElement("div");
          row.className = "expense";

          const amount = document.createElement("strong");
          amount.textContent = Number(expense.amount).toFixed(2);

          const details = document.createElement("div");
          details.textContent = expense.category;
          if (expense.note) {
            const note = document.createElement("div");
            note.className = "expense-note";
            note.textContent = expense.note;
            details.appendChild(note);
          }

          const date = document.createElement("span");
          date.className = "expense-date";
          date.textContent = expense.date;

          const remove = document.createElement("button");
          remove.type = "button";
          remove.className = "exp-del";
          remove.textContent = "Delete";
          remove.addEventListener("click", function () {
            expenses = expenses.filter(function (item) {
              return item.id !== expense.id;
            });
            saveExpenses();
            render();
          });

          row.append(amount, details, date, remove);
          list.appendChild(row);
        });

        const visibleTotal = visible.reduce(function (sum, expense) {
          return sum + Number(expense.amount);
        }, 0);
        total.textContent = visibleTotal.toFixed(2);

        categories.forEach(function (category) {
          const categoryTotal = visible.reduce(function (sum, expense) {
            return sum + (expense.category === category ? Number(expense.amount) : 0);
          }, 0);
          const element = document.querySelector('.cat-total[data-cat="' + category + '"]');
          element.textContent = category.charAt(0).toUpperCase() + category.slice(1) +
            ": " + categoryTotal.toFixed(2);
        });
      }

      form.addEventListener("submit", function (event) {
        event.preventDefault();
        const amount = Number(amountInput.value);

        if (!amountInput.value || !Number.isFinite(amount) || amount <= 0 || !dateInput.value) {
          error.textContent = "Enter a positive amount and select a date.";
          return;
        }

        expenses.unshift({
          id: Date.now().toString(36) + Math.random().toString(36).slice(2),
          amount: amount,
          category: categoryInput.value,
          date: dateInput.value,
          note: noteInput.value.trim()
        });

        saveExpenses();
        error.textContent = "";
        amountInput.value = "";
        noteInput.value = "";
        render();
      });

      [filterCategory, filterFrom, filterTo].forEach(function (control) {
        control.addEventListener("change", render);
      });

      render();
    }());
  </script>
</body>
</html>
